#!/usr/bin/env bash
# lib/adapters/wbft.sh - Adapter stub for go-wbft (gwbft)
# TODO: Implement when gwbft support is needed.

[[ -n "${_CB_ADAPTER_WBFT_LOADED:-}" ]] && return 0
readonly _CB_ADAPTER_WBFT_LOADED=1

_cb_wbft_not_implemented() {
  echo "ERROR: gwbft adapter is not yet implemented. Use chain.type=stablenet for now." >&2
  return 1
}

adapter_generate_genesis()          { _cb_wbft_not_implemented; }
adapter_generate_toml()             { _cb_wbft_not_implemented; }
adapter_extra_start_flags()         { printf '--allow-insecure-unlock\n'; }
adapter_consensus_rpc_namespace()   { printf 'istanbul\n'; }
adapter_binary_name()               { printf 'gwbft\n'; }

// Package adapters exposes a chain-type-agnostic init layer for future
// chainbench-net subcommands.
//
// The Adapter interface (defined in the sibling `spec` package and
// re-exported here so callers need only one import) defines:
//
//   - GenerateGenesis
//   - GenerateToml
//   - ExtraStartFlags
//   - ConsensusRpcNamespace
//
// Bash adapters under lib/adapters/ remain the active `chainbench init`
// execution path. This package is additive — a future sprint will wire it
// into a chainbench-net init/bootstrap handler. Drop-in replacement of the
// bash flow is explicitly out of scope for Sprint 3c.
package adapters

import (
	"github.com/0xmhha/chainbench/network/internal/adapters/spec"
	"github.com/0xmhha/chainbench/network/internal/adapters/stablenet"
	"github.com/0xmhha/chainbench/network/internal/adapters/wbft"
	"github.com/0xmhha/chainbench/network/internal/adapters/wemix"
)

// Re-exports so callers only need to import this package.
type (
	Adapter      = spec.Adapter
	GenesisInput = spec.GenesisInput
	TomlInput    = spec.TomlInput
	Role         = spec.Role
	Profile      = spec.Profile
	Metadata     = spec.Metadata
)

const (
	RoleValidator = spec.RoleValidator
	RoleEndpoint  = spec.RoleEndpoint

	// FeeDelegateDynamicFeeTxType is re-exported so the handler package can
	// reference the canonical 0x16 byte without importing spec directly.
	FeeDelegateDynamicFeeTxType = spec.FeeDelegateDynamicFeeTxType
)

var (
	ErrUnknownChainType = spec.ErrUnknownChainType
	ErrNotImplemented   = spec.ErrNotImplemented
)

// Load returns the Adapter registered for chainType, or ErrUnknownChainType
// when no adapter handles it.
func Load(chainType string) (Adapter, error) {
	switch chainType {
	case "stablenet":
		return stablenet.New(), nil
	case "wbft":
		return wbft.New(), nil
	case "wemix":
		return wemix.New(), nil
	default:
		return nil, ErrUnknownChainType
	}
}

