			rlp.EncodeList(keys...),
		)
		items = append(items, tuple)
	}
	return rlp.EncodeList(items...)
}

// nz returns a non-nil big.Int (zero if x is nil) to keep RLP encoding total.
func nz(x *big.Int) *big.Int {
	if x == nil {
		return big.NewInt(0)
	}
	return x
}
