package protocol

import "fmt"

// registry holds the built-in protocol presets keyed by chain name.
var registry = map[string]func() Protocol{
	"stablenet": StableNet,
	"wbft":      WBFT,
}

// ByName returns the protocol profile for the named chain. The error names the
// unknown chain and the known set so callers can surface an actionable message.
func ByName(name string) (Protocol, error) {
	if f, ok := registry[name]; ok {
		return f(), nil
	}
	return Protocol{}, fmt.Errorf("protocol: unknown chain %q (known: %v)", name, Names())
}

// Names returns the sorted list of registered chain names.
func Names() []string {
	names := make([]string, 0, len(registry))
	for n := range registry {
		names = append(names, n)
	}
	// small n; insertion sort keeps output deterministic without importing sort
	for i := 1; i < len(names); i++ {
		for j := i; j > 0 && names[j-1] > names[j]; j-- {
			names[j-1], names[j] = names[j], names[j-1]
		}
	}
	return names
}

// Register adds or overrides a protocol preset. Intended for consumers (e.g.
// chainbench) that supply additional chains not built into the SDK. It is not
// safe for concurrent use with ByName; register during init.
func Register(name string, f func() Protocol) {
	registry[name] = f
}

