package protocol

import (
	"testing"

	"github.com/0xmhha/accounts/tx"
)

// TestBaselineTxTypes_SharedIncludingFeeDelegation pins the A0 finding that the
// 0x16 fee-delegation type is shared by all target chains, not stablenet-only.
func TestBaselineTxTypes_SharedIncludingFeeDelegation(t *testing.T) {
	for _, p := range []Protocol{StableNet(), WBFT()} {
		if !p.SupportsTxType(tx.FeeDelegateDynamicFeeTxType) {
			t.Errorf("%s: expected 0x16 fee-delegation support", p.Name)
		}
		for _, std := range []byte{
			tx.LegacyTxType, tx.AccessListTxType, tx.DynamicFeeTxType,
			tx.BlobTxType, tx.SetCodeTxType,
		} {
			if !p.SupportsTxType(std) {
				t.Errorf("%s: expected standard tx type 0x%02x support", p.Name, std)
			}
		}
	}
}

// TestAccountModel_ExtraIsStablenetOnly pins the A0 finding that the Extra
// bitmap exists only on stablenet.
func TestAccountModel_ExtraIsStablenetOnly(t *testing.T) {
	if !StableNet().HasExtra() {
		t.Error("stablenet: expected Extra account model")
	}
	if WBFT().HasExtra() {
		t.Error("wbft: expected plain account model (no Extra)")
	}
}

// TestContracts_PerChainLayout pins that the system-contract layout differs per
// chain even within the wbft consensus family.
func TestContracts_PerChainLayout(t *testing.T) {
	sn := StableNet()
	if a, ok := sn.Contract(RoleNativeCoinAdapter); !ok || a.Hex() != "0x0000000000000000000000000000000000001000" {
		t.Errorf("stablenet NativeCoinAdapter: got %v ok=%v, want 0x..1000", a.Hex(), ok)
	}
	if a, ok := sn.Contract(RoleGovValidator); !ok || a.Hex() != "0x0000000000000000000000000000000000001001" {
