// Package protocol makes the accounts SDK multi-chain by capturing the
// per-chain facts that vary across go-stablenet / go-wbft / go-wemix while the
// cryptographic core (crypto, signing, keystore, the standard 0x00–0x04 tx
// encodings) stays shared.
//
// # What varies vs what is shared
//
// A0 spike (chainbench docs/A0-ACCOUNTS-MULTICHAIN-SCOPE.md) established, from
// the chain sources' core/types and params:
//
//   - Signing crypto is common: all three chains sign with secp256k1.
//   - Standard tx types 0x00–0x04 are common Ethereum encodings.
//   - The 0x16 fee-delegation tx type is present on ALL THREE chains (not
//     stablenet-only) — its byte-level envelope equivalence is verified
//     separately by golden vectors; here we only record that the type is
//     supported.
//   - The account Extra bitmap (blacklisted/authorized) is stablenet-ONLY
//     (go-wbft / go-wemix have no Extra field in StateAccount).
//   - System-contract layouts differ PER CHAIN, even within the same "wbft"
//     consensus family: stablenet exposes GovValidator@0x1001 +
//     NativeCoinAdapter@0x1000, while go-wbft exposes GovConfig@0x1000 +
//     GovStaking@0x1001. So the contract profile is keyed per chain, not per
//     consensus family.
//
// This package is ADDITIVE and backward-compatible: it does not move or change
// the existing account/governance/token/transport packages. Their existing
// Default* addresses remain the stablenet defaults; a Protocol simply provides
// the same facts in a chain-selectable form so a multi-chain consumer (e.g.
// chainbench) can pick a chain by name and get the right tx-type set, account
// model, and system-contract addresses.
package protocol

import (
	"github.com/0xmhha/accounts/tx"
	"github.com/0xmhha/accounts/types"
)

// Contract role names. Using stable string keys (rather than fixed struct
// fields) keeps the set open for chains whose governance layout differs.
const (
	// stablenet (anzeon) system contracts.
	RoleGovValidator      = "govValidator"      // 0x1001
	RoleNativeCoinAdapter = "nativeCoinAdapter" // 0x1000
	RoleGovMasterMinter   = "govMasterMinter"   // 0x1002
	RoleGovMinter         = "govMinter"         // 0x1003
	RoleGovCouncil        = "govCouncil"        // 0x1004

	// go-wbft system contracts.
	RoleGovConfig      = "govConfig"      // 0x1000
	RoleGovStaking     = "govStaking"     // 0x1001
	RoleGovRewardeeImp = "govRewardeeImp" // 0x1002
	RoleGovNCP         = "govNCP"         // 0x1003
)

// AccountModel names the account-state layout a chain uses.
type AccountModel string

const (
	// AccountPlain is a stock go-ethereum StateAccount (no Extra word).
	AccountPlain AccountModel = "plain"
	// AccountStableNetExtra adds the stablenet 64-bit Extra flag word
	// (bit 63 blacklisted, bit 62 authorized). See account.Extra.
	AccountStableNetExtra AccountModel = "stablenet-extra"
)

// ContractModel names how a chain locates its system contracts.
type ContractModel string

const (
	// ContractFixed means system contracts sit at genesis-fixed addresses
	// (stablenet: 0x1000–0x1004; wbft: 0x1000–0x1003). Protocol.Contracts is
	// populated.
	ContractFixed ContractModel = "fixed"
	// ContractRegistry means contracts are resolved at runtime through a
	// Registry contract by role name (go-wemix). Their addresses are not
	// known statically, so Protocol.Contracts is empty and callers resolve
	// via the on-chain Registry. See Protocol.ContractRoles for the role
	// names wemix exposes.
	ContractRegistry ContractModel = "registry"
)

// Protocol is the per-chain profile the accounts SDK needs to build and read
// transactions and account state for one chain. It is data only; behavior
// lives in the existing crypto/tx/signing packages, parameterized by these
// facts.
type Protocol struct {
	// Name is the chain identifier, matching chainbench chain ids
	// ("stablenet" | "wbft" | "wemix").
	Name string

	// TxTypes is the set of EIP-2718 tx type bytes this chain accepts.
	TxTypes []byte

	// Account is the account-state model (whether the Extra word exists).
	Account AccountModel

	// EIP712Name is the EIP-712 domain name used for typed-data signing on
	// this chain. Empty means not yet specified for this chain.
	EIP712Name string

	// ContractSystem is how system contracts are located (fixed vs registry).
	ContractSystem ContractModel

	// Contracts maps a role name (Role* const) to its system-contract
	// address, for ContractFixed chains. A role absent from the map is not
	// present on the chain. Empty for ContractRegistry chains.
	Contracts map[string]types.Address

	// ContractRoles lists the role names a ContractRegistry chain resolves
	// via its Registry (go-wemix: Gov, Staking, BallotStorage, EnvStorage,
	// NCPExit). Empty for ContractFixed chains (use Contracts instead).
	ContractRoles []string
}

