package protocol

import (
	"testing"

	"github.com/0xmhha/accounts/tx"
)

// TestBaselineTxTypes_SharedIncludingFeeDelegation pins the A0 finding that the
// 0x16 fee-delegation type is shared by all target chains, not stablenet-only.
func TestBaselineTxTypes_SharedIncludingFeeDelegation(t *testing.T) {
	for _, p := range []Protocol{StableNet(), WBFT(), WeMix()} {
		if !p.SupportsTxType(tx.FeeDelegateDynamicFeeTxType) {
			t.Errorf("%s: expected 0x16 fee-delegation support", p.Name)
		}
		for _, std := range []byte{
			tx.LegacyTxType, tx.AccessListTxType, tx.DynamicFeeTxType,
			tx.BlobTxType, tx.SetCodeTxType,
		} {
			if !p.SupportsTxType(std) {
				t.Errorf("%s: expected standard tx type 0x%02x support", p.Name, std)
			}
		}
	}
}

// TestAccountModel_ExtraIsStablenetOnly pins the A0 finding that the Extra
// bitmap exists only on stablenet.
func TestAccountModel_ExtraIsStablenetOnly(t *testing.T) {
	if !StableNet().HasExtra() {
		t.Error("stablenet: expected Extra account model")
	}
	if WBFT().HasExtra() {
		t.Error("wbft: expected plain account model (no Extra)")
	}
	if WeMix().HasExtra() {
		t.Error("wemix: expected plain account model (no Extra)")
	}
}

// TestContractModel_WemixIsRegistry pins that wemix resolves contracts via a
// Registry (no genesis-fixed addresses) while stablenet/wbft are fixed.
func TestContractModel_WemixIsRegistry(t *testing.T) {
	if StableNet().ContractSystem != ContractFixed {
		t.Error("stablenet: expected ContractFixed")
	}
	if WBFT().ContractSystem != ContractFixed {
		t.Error("wbft: expected ContractFixed")
	}
	wm := WeMix()
	if wm.ContractSystem != ContractRegistry {
		t.Error("wemix: expected ContractRegistry")
	}
	if len(wm.Contracts) != 0 {
		t.Errorf("wemix: expected empty fixed Contracts, got %d", len(wm.Contracts))
	}
	if len(wm.ContractRoles) == 0 {
		t.Error("wemix: expected non-empty ContractRoles for registry resolution")
	}
}

// TestContracts_PerChainLayout pins that the system-contract layout differs per
// chain even within the wbft consensus family.
func TestContracts_PerChainLayout(t *testing.T) {
	sn := StableNet()
	if a, ok := sn.Contract(RoleNativeCoinAdapter); !ok || a.Hex() != "0x0000000000000000000000000000000000001000" {
		t.Errorf("stablenet NativeCoinAdapter: got %v ok=%v, want 0x..1000", a.Hex(), ok)
	}
	if a, ok := sn.Contract(RoleGovValidator); !ok || a.Hex() != "0x0000000000000000000000000000000000001001" {
		t.Errorf("stablenet GovValidator: got %v ok=%v, want 0x..1001", a.Hex(), ok)
	}
	// wbft uses a different layout: GovConfig@0x1000, GovStaking@0x1001.
	wb := WBFT()
	if a, ok := wb.Contract(RoleGovConfig); !ok || a.Hex() != "0x0000000000000000000000000000000000001000" {
		t.Errorf("wbft GovConfig: got %v ok=%v, want 0x..1000", a.Hex(), ok)
	}
	if a, ok := wb.Contract(RoleGovStaking); !ok || a.Hex() != "0x0000000000000000000000000000000000001001" {
		t.Errorf("wbft GovStaking: got %v ok=%v, want 0x..1001", a.Hex(), ok)
	}
	// wbft must NOT carry stablenet's role keys.
	if _, ok := wb.Contract(RoleGovValidator); ok {
		t.Error("wbft: unexpected stablenet GovValidator role present")
	}
}

func TestByName(t *testing.T) {
	for _, name := range []string{"stablenet", "wbft", "wemix"} {
		p, err := ByName(name)
		if err != nil {
			t.Fatalf("ByName(%q): %v", name, err)
		}
		if p.Name != name {
			t.Errorf("ByName(%q): got Name %q", name, p.Name)
		}
	}
	if _, err := ByName("nope"); err == nil {
		t.Error("ByName(nope): expected error")
	}
}

func TestNames_Sorted(t *testing.T) {
	got := Names()
	want := []string{"stablenet", "wbft"}
	if len(got) != len(want) {
		t.Fatalf("Names(): got %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("Names(): got %v, want %v", got, want)
		}
	}
}

