1	// Package config implements the three-source configuration resolution required
2	// by the chain setup surface (requirement #4): a value may come from a code
3	// default, a config file, or a runtime flag/env override, with later sources
4	// winning. Resolution produces one merged view that every pipeline phase and
5	// driver consumes, removing the current three-way SSOT split
6	// (defaults.generated.sh / profile YAML / flags) — see
7	// docs/CHAINBENCH_GO_REDESIGN.md §6.
8	//
9	// Config is represented as flat dot-path keys (e.g. "ports.base_http") mirroring
10	// the existing profile schema, so the package stays free of any file format:
11	// callers Flatten a parsed YAML/JSON map into Values and Merge the layers.
12	package config
13	
14	import (
15		"strconv"
16		"time"
17	)
18	
19	// Values is a flat map of dot-path key to raw string value.
20	type Values map[string]string
21	
22	// Defaults returns the canonical code-default layer. These mirror
23	// network/schema/defaults.json and the profile defaults so a bare setup with no
24	// file or flags still resolves to a working local chain.
25	func Defaults() Values {
26		return Values{
27			"chain":              "stablenet",
28			"nodes.validators":   "4",
29			"nodes.endpoints":    "1",
30			"nodes.verbosity":    "3",
31			"nodes.gcmode":       "full",
32			"nodes.cache":        "1024",
33			"data.directory":     "data",
34			"keys.mode":          "static",
35			"keys.source":        "keys/preset",
36			"ports.base_p2p":     "30301",
37			"ports.base_http":    "8501",
38			"ports.base_ws":      "9501",
39			"ports.base_auth":    "8551",
40			"ports.base_metrics": "6061",
41			"logging.rotation":   "true",
42			"logging.max_size":   "10M",
43			"logging.max_files":  "5",
44			"logging.directory":  "data/logs",
45		}
46	}
47	
48	// Merge overlays layers left-to-right: a key set in a later layer overrides the
49	// same key in an earlier one. Empty-string values still override (an explicit
50	// clear); callers wanting "unset" should omit the key. The result is a fresh
51	// map; inputs are not mutated.
52	func Merge(layers ...Values) Values {
53		out := Values{}
54		for _, layer := range layers {
55			for k, v := range layer {
56				out[k] = v
57			}
58		}
59		return out
60	}
61	
62	// Resolve is the standard three-source resolution: Defaults() first, then the
63	// file layer, then the override (flag/env) layer.
64	func Resolve(file, override Values) Values {
65		return Merge(Defaults(), file, override)
66	}
67	
68	// Flatten converts a nested map (as decoded from YAML/JSON) into dot-path
69	// Values. Nested maps recurse; scalars are stringified; slices/other complex
70	// values are skipped (they are handled by chain-specific code, not the core
71	// resolver). Keys with non-string map keys are ignored.
72	func Flatten(nested map[string]any) Values {
73		out := Values{}
74		flattenInto(out, "", nested)
75		return out
76	}
77	
78	func flattenInto(out Values, prefix string, m map[string]any) {
79		for k, v := range m {
80			key := k
81			if prefix != "" {
82				key = prefix + "." + k
83			}
84			switch t := v.(type) {
85			case map[string]any:
86				flattenInto(out, key, t)
87			case nil:
88				// skip: absence, not an explicit clear
89			case string:
90				out[key] = t
91			case bool:
92				out[key] = strconv.FormatBool(t)
93			case int:
94				out[key] = strconv.Itoa(t)
95			case int64:
96				out[key] = strconv.FormatInt(t, 10)
97			case float64:
98				// JSON numbers decode as float64; render integers without a
99				// trailing ".0" so "8283" stays "8283".
100				if t == float64(int64(t)) {
101					out[key] = strconv.FormatInt(int64(t), 10)
102				} else {
103					out[key] = strconv.FormatFloat(t, 'f', -1, 64)
104				}
105			default:
106				// slices, structs, etc. are not core-resolver concerns; skip.
107			}
108		}
109	}
110	
111	// String returns the value for key, or def if absent.
112	func (v Values) String(key, def string) string {
113		if s, ok := v[key]; ok {
114			return s
115		}
116		return def
117	}
118	
119	// Int returns the value for key parsed as an int, or def if absent/unparseable.
120	func (v Values) Int(key string, def int) int {
121		if s, ok := v[key]; ok {
122			if n, err := strconv.Atoi(s); err == nil {
123				return n
124			}
125		}
126		return def
127	}
128	
129	// Bool returns the value for key parsed as a bool, or def if absent/unparseable.
130	// Accepts the usual truthy strings (true/false/1/0/yes/no, case-insensitive).
131	func (v Values) Bool(key string, def bool) bool {
132		if s, ok := v[key]; ok {
133			switch s {
134			case "true", "True", "TRUE", "1", "yes", "Yes", "YES", "on":
135				return true
136			case "false", "False", "FALSE", "0", "no", "No", "NO", "off":
137				return false
138			}
139		}
140		return def
141	}
142	
