// Package accounts is chainbench's boundary over the accounts SDK
// (github.com/0xmhha/accounts). AccountProvider is chainbench-owned so the rest
// of chainbench does not couple to the SDK's concrete types; the default
// implementation is backed by the SDK's per-chain protocol profiles
// (decision D3 — interface boundary + SDK default impl).
//
// The faucet primitive (requirement #3) and tx building will attach to this
// provider as the setup/tx phases land (G1); G0 establishes the boundary and
// the protocol wiring so a chain plugin can already report its tx-type set,
// account model, and system-contract layout through one seam.
package accounts

import (
	"github.com/0xmhha/accounts/protocol"
)

// AccountProvider is the chainbench-facing account/tx capability for one chain.
// It is intentionally small at G0; NewWallet/Faucet/BuildTx are added in G1.
type AccountProvider interface {
	// Protocol returns the underlying accounts SDK protocol profile.
	Protocol() protocol.Protocol
	// SupportsTxType reports whether the chain accepts the given EIP-2718 tx
	// type byte (e.g. 0x16 fee delegation).
	SupportsTxType(t byte) bool
	// HasAccountExtra reports whether the chain uses the stablenet Extra
	// account-state model (blacklisted/authorized bits).
	HasAccountExtra() bool
}

