			Host:       host,
			Binary:     m.Binary,
			DataDir:    dataDir,
			ConfigPath: configPath,
			LogPath:    filepath.Join(dataRoot, "logs", fmt.Sprintf("node%d.log", i)),
			Ports:      ports,
