)

type plugin struct {
	m    registry.Manifest
	tmpl []byte
}

func init() {
	raw, err := manifests.Raw("stablenet")
	if err != nil {
		panic(err)
	}
	m, err := registry.ParseManifest(raw)
	if err != nil {
		panic(err)
	}
	var tmpl []byte
	if m.Genesis.Template != "" {
		if tmpl, err = manifests.GenesisTemplate(m.Genesis.Template); err != nil {
			panic(err)
		}
	}
	registry.Register(plugin{m: m, tmpl: tmpl})
}

