func TestSetupCmd_ProvisionWritesRealGenesis(t *testing.T) {
	dir := t.TempDir()
	out, err := run(t, "setup",
		"--chain", "stablenet",
		"--validators", "4", "--endpoints", "1",
		"--data-dir", dir,
		"--keys-dir", filepath.Join("..", "..", "keys", "preset"),
		"--provision",
	)
	if err != nil {
		t.Fatalf("provision: %v\n%s", err, out)
