	if isErr || !strings.HasPrefix(text, "tx: 0x") {
		t.Errorf("faucet tool: err=%v text=%s", isErr, text)
	}
}

func hexInt(n int) string {
	const d = "0123456789abcdef"
	if n == 0 {
		return "0"
	}
	var b []byte
	for n > 0 {
		b = append([]byte{d[n%16]}, b...)
		n /= 16
	}
	return string(b)
}

