			var b strings.Builder
			var ok, failed int
			for _, r := range runs {
				fmt.Fprintf(&b, "%s [%s] %s %s\n", r.ID, r.Phase, r.Chain, r.Status)
				switch r.Status {
				case obs.RunSucceeded:
					ok++
				case obs.RunFailed:
					failed++
				}
			}
			fmt.Fprintf(&b, "total=%d ok=%d failed=%d", len(runs), ok, failed)
			return b.String(), nil
		},
	}
}

