38	func reportTool() Tool {
39		return Tool{
40			Name:        "chainbench_report",
41			Description: "Read stored run/test results from a setup's data dir. Args: data_dir.",
42			InputSchema: map[string]any{
43				"type": "object",
44				"properties": map[string]any{
45					"data_dir": map[string]any{"type": "string"},
46				},
47				"required": []string{"data_dir"},
48			},
49			Handler: func(_ context.Context, args map[string]any) (string, error) {
50				dir := argString(args, "data_dir", "")
51				if dir == "" {
52					return "", fmt.Errorf("data_dir is required")
53				}
54				store, err := obs.NewFileStore(filepath.Join(dir, "runs.json"))
55				if err != nil {
56					return "", err
57				}
58				runs := store.ListRuns()
59				if len(runs) == 0 {
60					return "no runs recorded", nil
61				}
62				var b strings.Builder
63				var ok, failed int
64				for _, r := range runs {
65					fmt.Fprintf(&b, "%s [%s] %s %s\n", r.ID, r.Phase, r.Chain, r.Status)
66					switch r.Status {
67					case obs.RunSucceeded:
68						ok++
69					case obs.RunFailed:
70						failed++
71					}
72				}
73				fmt.Fprintf(&b, "total=%d ok=%d failed=%d", len(runs), ok, failed)
74				return b.String(), nil
75			},
76		}
77	}
